52		// 字段名比较的是转义还原后的字符，所以这些用例都必须判重。
53		sameValue := []string{
54			`[{"name":"m","\u006eame":"m","timestamp":1,"value":1}]`,
55			`[{"name":"m","timestamp":1,"\u0074imestamp":1,"value":1}]`,
56			`[{"name":"m","timestamp":1,"value":1,"\u0076alue":1}]`,
