211	// TestSameConcatenatedTextDifferentKeySplit 针对长度前缀身份签名自身的边界：
212	// 若把键值直接拼接，冒号/分号会被当成边界，使不同的键值划分产生同一段文本。
213	// 这些输入在朴素拼接表示下两两碰撞，但必须是四条不同序列：
214	//
215	//	A {"a":"b:c"} 与 B {"a:b":"c"}：朴素拼接都是 a:b:c
216	//	C {"a":"b;x:y"} 与 D {"a":"b","x":"y"}（值看起来像两个标签）：朴素拼接都是 a:b;x:y
217	func TestSameConcatenatedTextDifferentKeySplit(t *testing.T) {
218		store := NewMetricStore()
219		res := mustOK(t, store, `[
220			{"name":"m","timestamp":1,"value":1,"labels":{"a":"b:c"}},
221			{"name":"m","timestamp":1,"value":2,"labels":{"a:b":"c"}},
222			{"name":"m","timestamp":1,"value":3,"labels":{"a":"b;x:y"}},
223			{"name":"m","timestamp":1,"value":4,"labels":{"a":"b","x":"y"}}
224		]`)
225		if res.Added != 4 || len(res.Series) != 4 {
226			t.Fatalf("same concatenated text, different key/value splits must stay distinct: %+v", res)
227		}
228		want := []map[string]string{
229			{"a": "b:c"},
230			{"a:b": "c"},
231			{"a": "b;x:y"},
232			{"a": "b", "x": "y"},
233		}
234		all := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":10}`)
235		if len(all.Series) != 4 {
236			t.Fatalf("query = %+v, want 4 series", all.Series)
237		}
238		for i, labels := range want {
239			found := false
240			for _, s := range all.Series {
241				if reflect.DeepEqual(s.Labels, labels) {
242					found = true
243					if s.Count != 1 || s.Average != float64(i+1) {
244						t.Fatalf("series %v must keep its own point, got count=%d average=%v",
245							labels, s.Count, s.Average)
246					}
247				}
248			}
249			if !found {
250				t.Fatalf("series %v missing from query result %+v (case %d)", labels, all.Series, i)
251			}
252		}
253		// 子集匹配按真实键值对：冒号在键里与在值里是不同的标签。
254		if got := queryOne(t, store, queryLabels("m", 0, 10, map[string]string{"a:b": "c"})); got.Average != 2 {
255			t.Fatalf("key-with-colon label match = %+v, want value 2", got)
256		}
257		if got := queryOne(t, store, queryLabels("m", 0, 10, map[string]string{"a": "b:c"})); got.Average != 1 {
258			t.Fatalf("value-with-colon label match = %+v, want value 1", got)
259		}
260		// "x=y" 只真实存在于两标签序列；单标签值里的 "x:y" 片段不产生标签 x。
261		if got := queryOne(t, store, queryLabels("m", 0, 10, map[string]string{"x": "y"})); got.Average != 4 {
262			t.Fatalf("x=y must match only the real two-label series, got %+v", got)
263		}
264	}
