315	// TestLookAlikeIdentitiesDoNotConflict：两条文本渲染完全相同的不同序列，在同一
316	// 时间戳分别提交不同数值不得互相冲突；随后对其中一条再改值才冲突，且冲突报告的
317	// 是结构化的真实完整标签集合，而不是有歧义的渲染文本。
318	func TestLookAlikeIdentitiesDoNotConflict(t *testing.T) {
319		store := NewMetricStore()
320		mustOK(t, store, `[{"name":"cpu","timestamp":1,"value":1,"labels":{"a":"b=2"}}]`)
321		// 单标签 a="b=2" 与两标签 a=1,b=2 的 String() 都是 cpu{a=b=2}，但身份不同。
322		res := mustOK(t, store, `[{"name":"cpu","timestamp":1,"value":2,"labels":{"a":"1","b":"2"}}]`)
323		if res.Added != 1 || res.Duplicates != 0 || len(res.Series) != 2 {
324			t.Fatalf("look-alike identities with different values must both be added, got %+v", res)
325		}
326		// 对单标签序列提交不同值：冲突，结构化标签只有一个键且值原样为 "b=2"。
327		lerr := mustFail(t, store, `[{"name":"cpu","timestamp":1,"value":9,"labels":{"a":"b=2"}}]`)
328		if lerr.Conflict == nil || lerr.Conflict.Existing != 1 || lerr.Conflict.Submitted != 9 {
329			t.Fatalf("single-label conflict values wrong: %+v", lerr.Conflict)
330		}
331		if labels := lerr.Conflict.Series.Labels; len(labels) != 1 || labels["a"] != "b=2" {
332			t.Fatalf("conflict must name real single-label identity, got %v", labels)
333		}
334		// 对两标签序列提交不同值同样冲突，结构化标签是两个键。
335		lerr = mustFail(t, store, `[{"name":"cpu","timestamp":1,"value":9,"labels":{"a":"1","b":"2"}}]`)
336		if lerr.Conflict == nil || lerr.Conflict.Existing != 2 {
337			t.Fatalf("two-label conflict values wrong: %+v", lerr.Conflict)
338		}
339		if labels := lerr.Conflict.Series.Labels; len(labels) != 2 || labels["a"] != "1" || labels["b"] != "2" {
340			t.Fatalf("conflict must name real two-label identity, got %v", labels)
341		}
342		// 两条序列原有采样点都保持各自的值，全量查询仍返回两条独立序列。
343		full := mustQuery(t, store, `{"op":"query","name":"cpu","start":0,"end":10}`)
344		if len(full.Series) != 2 {
345			t.Fatalf("full cpu query = %+v, want 2 series", full.Series)
346		}
347		for _, s := range full.Series {
348			if s.Count != 1 {
349				t.Fatalf("series %v must keep its own point, got count=%d", s.Labels, s.Count)
350			}
351		}
352	}
