354	// TestWhitespaceInIdentityPreservedVerbatim：名称、标签键和值中的合法空格原样
355	// 保留，不能通过去空格把不同输入合并为同一序列。
356	func TestWhitespaceInIdentityPreservedVerbatim(t *testing.T) {
357		store := NewMetricStore()
358		res := mustOK(t, store, `[
359			{"name":"m ","timestamp":1,"value":1,"labels":{"k ":"v"}},
360			{"name":"m","timestamp":1,"value":2,"labels":{"k":"v"}},
361			{"name":"m","timestamp":1,"value":3,"labels":{"k":" v"}},
362			{"name":"m","timestamp":1,"value":4,"labels":{"k":"v "}},
363			{"name":"m","timestamp":1,"value":5,"labels":{" k":"v"}}
364		]`)
365		if res.Added != 5 || len(res.Series) != 5 {
366			t.Fatalf("whitespace variants must be 5 distinct series, got added=%d series=%d", res.Added, len(res.Series))
367		}
368		cases := []struct {
369			name   string
370			labels map[string]string
371			value  float64
372		}{
373			{"m ", map[string]string{"k ": "v"}, 1},
374			{"m", map[string]string{"k": "v"}, 2},
375			{"m", map[string]string{"k": " v"}, 3},
376			{"m", map[string]string{"k": "v "}, 4},
377			{"m", map[string]string{" k": "v"}, 5},
378		}
379		for i, c := range cases {
380			var line string
381			if c.name == "m" {
382				line = queryLabels("m", 0, 10, c.labels)
383			} else {
384				line = `{"op":"query","name":` + jsonString(c.name) + `,"start":0,"end":10,"labels":` + jsonLabels(c.labels) + `}`
385			}
386			got := queryOne(t, store, line)
387			if got.Name != c.name || !reflect.DeepEqual(got.Labels, c.labels) || got.Average != c.value {
388				t.Fatalf("whitespace case %d: got %+v, want name=%q labels=%v value=%v", i, got, c.name, c.labels, c.value)
389			}
390		}
391		// 省略标签与空标签对象同一身份；缺标签与标签存在且值为空串仍是不同身份，
392		// 即使标签键周围带有合法空格。
393		mustOK(t, store, `[{"name":"n","timestamp":1,"value":1}]`)
394		if dup := mustOK(t, store, `[{"name":"n","timestamp":1,"value":1.0,"labels":{}}]`); dup.Added != 0 || dup.Duplicates != 1 {
395			t.Fatalf("omitted vs empty labels must be the same series, got %+v", dup)
396		}
397		if added := mustOK(t, store, `[{"name":"n","timestamp":1,"value":2,"labels":{" z ":""}}]`); added.Added != 1 {
398			t.Fatalf("missing label differs from present empty value, added = %d", added.Added)
399		}
400		// 快照中 n 现在有两条独立序列：无标签与带空值标签（连同 m 的五条共七条）。
401		nSeries := 0
402		for _, v := range mustOK(t, store, `[]`).Series {
403			if v.Name == "n" {
404				nSeries++
405			}
406		}
407		if nSeries != 2 {
408			t.Fatalf("metric n must have 2 distinct series, got %d", nSeries)
409		}
410		got := queryOne(t, store, queryLabels("n", 0, 10, map[string]string{" z ": ""}))
411		if len(got.Labels) != 1 || got.Labels[" z "] != "" || got.Average != 2 {
412			t.Fatalf("spaced-key empty-value label not preserved: %+v", got)
413		}
414	}
