416	// TestDelimiterLabelSubsetMatching：子集匹配按真实键值对进行，值里的分隔符既不会
417	// 制造额外的匹配标签，也不会让需要的标签匹配失败；不同序列的点不混合。
418	func TestDelimiterLabelSubsetMatching(t *testing.T) {
419		store := NewMetricStore()
420		mustOK(t, store, `[
421			{"name":"m","timestamp":1,"value":10,"labels":{"a":"x","b":"y=z"}},
422			{"name":"m","timestamp":1,"value":20,"labels":{"a":"x","b":"q"}},
423			{"name":"m","timestamp":1,"value":30,"labels":{"a":"x","b":"y=z","c":"d,e"}}
424		]`)
425		// a=x 子集命中三条，各自独立返回自己的点与均值。
426		res := mustQuery(t, store, queryLabels("m", 0, 10, map[string]string{"a": "x"}))
427		if len(res.Series) != 3 {
428			t.Fatalf("a=x subset = %+v, want 3 series", res.Series)
429		}
430		// b="y=z" 只命中真实拥有该键值的两条（含带额外标签 c 的一条），不命中 b=q。
431		res = mustQuery(t, store, queryLabels("m", 0, 10, map[string]string{"b": "y=z"}))
432		if len(res.Series) != 2 {
433			t.Fatalf("b=y=z subset = %+v, want 2 series", res.Series)
434		}
435		wantAvgs := map[int]bool{10: false, 30: false}
436		for _, s := range res.Series {
437			if s.Count != 1 {
438				t.Fatalf("matched series %v must report its own single point, got count=%d", s.Labels, s.Count)
439			}
440			if _, ok := wantAvgs[int(s.Average)]; !ok {
441				t.Fatalf("unexpected average %v from %v", s.Average, s.Labels)
442			}
443			wantAvgs[int(s.Average)] = true
444		}
445		for v, seen := range wantAvgs {
446			if !seen {
447				t.Fatalf("series with average %d was not matched separately", v)
448			}
449		}
450		// 查询值里写逗号文本是完整值比较：只有值恰好为 "d,e" 的标签能匹配。
451		if got := queryOne(t, store, queryLabels("m", 0, 10, map[string]string{"c": "d,e"})); got.Average != 30 {
452			t.Fatalf("comma-in-value subset = %+v, want average 30", got)
453		}
454		if len(mustQuery(t, store, queryLabels("m", 0, 10, map[string]string{"d": "e"})).Series) != 0 {
455			t.Fatalf("value fragment d,e must not be split into label d=e")
456		}
457	}
458

